import torch


def gen_inputs(ctx, device):
    import torch
    shape = tuple(ctx["y__shape"])
    dtype = getattr(torch, ctx["y__dtype"])
    # keep ``other`` positive so ``log`` stays finite for a clean comparison
    y = torch.rand(shape, dtype=dtype, device=device) * 5.0 + 0.01
    return {"y": y}


def run_correctness(x, y):
    return torch.xlogy(x.float(), y.float()).to(x.dtype)


def run(x, y):
    return torch.xlogy(x, y)
